                return 2;
            case RETIRADA_LOJA:
                return 1;
            case MOTOBOY:
                return 0;
            default:
                return 0;
        }
    }

    private BigDecimal calcularSeguro(BigDecimal subtotal, Regiao regiao) {
        BigDecimal taxa = switch (regiao) {
