            case BRONZE:
            default:
                return ZERO.setScale(SCALE, ROUNDING);
        }
    }

    private boolean verificarBrinde(BigDecimal subtotal, NivelClube nivel) {
        return nivel == NivelClube.OURO && subtotal.compareTo(new BigDecimal("500.00")) > 0;
    }
}

