    }

    private BigDecimal calcularValorParcela(BigDecimal total, int parcelas, FormaPagamento forma) {
        if (forma == FormaPagamento.CARTAO && parcelas > 3) {
            BigDecimal taxa = new BigDecimal("0.0199");
